package service;

import dto.BookResponseDTO;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Nghiep vu sach: sap xep va danh so cac dong bang Controller dua vao.
 * Service CHI xu ly du lieu duoc dua vao — khong tao, khong goi kho (repository).
 *
 * @author CuongThai Academy
 */
public class BookService {

    // Service khong giu du lieu nao
    public BookService() {
    }

    // Sap cac dong bang theo ten (A-Z, khong phan biet hoa thuong), trung ten thi theo ISBN;
    // xong danh so thu tu tu 1
    public List<BookResponseDTO> sortByTitle(List<BookResponseDTO> bookList) {
        // Ban sao de khong lam doi thu tu cua danh sach goc
        List<BookResponseDTO> sortedList = new ArrayList<>(bookList);

        // Comparator la "luat so": tra so am neu first dung truoc second
        Collections.sort(sortedList, new Comparator<BookResponseDTO>() {
            // So ten truoc, trung ten thi so ISBN
            @Override
            public int compare(BookResponseDTO first, BookResponseDTO second) {
                // Ket qua so ten (0 = trung ten)
                int byTitle = first.getTitle().compareToIgnoreCase(second.getTitle());

                // Trung ten thi ISBN quyet dinh thu tu
                if (byTitle == 0) {
                    return first.getIsbn().compareTo(second.getIsbn());
                }

                return byTitle;
            }
        });

        // Danh so thu tu sau khi sap xep
        for (int i = 0; i < sortedList.size(); i++) {
            sortedList.get(i).setNo(i + 1);
        }

        return sortedList;
    }
}

